const contentPattern=/^CONTENT\/(?:RU|EN|DE|ZH-HANS|KO|FR|JA|HI|ES|AR)\/(?:WORKING|RPTKA|WLKP|WORKING_CONVERSION|KNOWLEDGE_WORKING_DOCUMENTS|KNOWLEDGE_WORKING_VS_E33G)(?:_RU_v1_REVIEW)?\.md$/;
const allowed=file=>Object.hasOwn(workingEvidenceHashes,file)||contentPattern.test(file);
export function createWorkingBundleReader(directory) {
  const root=resolve(directory);assert.ok(lstatSync(root).isDirectory()&&!lstatSync(root).isSymbolicLink()&&realpathSync(root)===root,'Unsafe bundle root');
  return file=>{
    assertDocumentsPath(file);assert.ok(allowed(file),'Not an allowed G01 source');let current=root;
    for(const [i,part] of file.split('/').entries()) {current=join(current,part);const s=lstatSync(current);assert.ok(!s.isSymbolicLink(),'Refuse symlink source');assert.ok(i===file.split('/').length-1?s.isFile():s.isDirectory(),'Not a regular source');}
    return readFileSync(current);
  };
}
export const workingLinks=body=>[...body.matchAll(/\]\((\/[^)\s]+)\)/g)].map(match=>match[1]);
export function readWorkingStructure(original,row) {
  const prefix=original.match(/^\*\*SEO Title:\*\* ([^\n]+)\n\*\*Meta Description:\*\* ([^\n]+)\n\n/);
  assert.ok(prefix,'Missing G01 SEO scaffold');assert.equal(prefix[1],row.seo.title);assert.equal(prefix[2],row.seo.description);
  const sourceBody=original.slice(prefix[0].length);assert.equal(sourceBody,row.body,'Full JSON/Markdown body drift');
  assert.equal(sha(sourceBody),row.bodySha256);assert.ok(sourceBody.endsWith('\n'));
  const cta=sourceBody.match(/^\*\*CTA:\*\* (.+)$/m);assert.ok(cta,'Missing G01 CTA');
  assert.equal((sourceBody.match(/^\*\*CTA:\*\*/gm)??[]).length,1);
  const body=sourceBody.replace(cta[0]+'\n',''),h1=body.match(/^# (.+)$/m),heads=[...body.matchAll(/^## (.+)$/gm)];
  assert.ok(h1&&body.startsWith(h1[0]+'\n'));assert.equal((body.match(/^# /gm)??[]).length,1);assert.equal(heads.length,8);
  // Every exact supplied locale has the same ordered structure: short answer,
  // detail sections, FAQ (six H3), and final discussion CTA. No translation.
  const faqHead=heads.at(-2),faqBody=body.slice(faqHead.index+faqHead[0].length,heads.at(-1).index),questions=[...faqBody.matchAll(/^### (.+)$/gm)];
  assert.equal((body.match(/^### /gm)??[]).length,6);assert.equal(questions.length,6);assert.equal(row.faqCount,6);
  const faq=questions.map((q,i)=>({question:q[1],answerMarkdown:faqBody.slice(q.index+q[0].length,questions[i+1]?.index??faqBody.length).trim()}));
  assert.ok(faq.every(q=>q.answerMarkdown));assert.deepEqual(workingLinks(sourceBody),row.links);
  assert.ok(!/<!--|-->|\{\{CATALOG_PRICE|\{\{USD|\b0\s*IDR\b/.test(body),'Staging/price leakage');
  return {body,h1:h1[1],directAnswer:body.slice(heads[0].index+heads[0][0].length,heads[1].index).trim(),directHeading:heads[0][1],
    factBlock:{heading:'',items:[]},faq,faqHeading:faqHead[1],cta:[{role:'primary',label:cta[1],actionIntent:'existing_contact_flow'}]};
}
const newShell=(id,spec)=>({contentId:id,kind:spec.kind,title:'',parentId:spec.parent,relatedContentIds:[],serviceId:null,pricingRef:null,
  bindingStatus:'not_applicable',availability:'not_verified',bindingEvidence:[],published:null,candidate:{route:spec.route,exposure:'preview_only',revision:'G01_PENDING',ru:{},translations:{}},
  reuseRoutes:[],mergeTargetId:null,duplicateRisk:null,release:'not_authorized',inlineLinkTargets:[]});

export function restorePreWorkingRegistry(current,history) {
  assert.equal(history?.schemaVersion,1);assert.equal(history.sourceRegistryRecordCount,157);
  assert.deepEqual(history.removeAddedContentIds,Object.keys(workingPages).filter(id=>!workingPages[id].oldSha));assert.equal(history.records.length,4);
  for(const [id,spec] of Object.entries(workingPages))if(spec.oldSha)assert.equal(sha(canonicalJson(history.records.find(r=>r.contentId===id))),spec.oldSha,'Pre-G01 draft history drift');
  const restored=structuredClone(current);restored.records=restored.records.filter(r=>!history.removeAddedContentIds.includes(r.contentId))
    .map(r=>structuredClone(history.records.find(old=>old.contentId===r.contentId)??r));
  assert.equal(restored.records.length,157);assert.equal(sha(bytes(restored)),history.sourceRegistrySha256,'Exact pre-G01 Registry restoration drift');return restored;
}

