    if(spec.oldSha){assert.ok(old,'Missing existing G01 identity');assert.equal(sha(canonicalJson(old)),spec.oldSha,'Concurrent existing G01 draft drift');}
    else assert.ok(!old,'Occupied G01 identity');
    for(const other of baseline.records.filter(r=>r.contentId!==id)) {
      assert.notEqual(other.candidate.route,spec.route,'Occupied G01 route');assert.ok(!other.reuseRoutes.includes(spec.route),'Occupied G01 reuse route');
      assert.ok(!Object.values(other.published?.routes??{}).some(path=>input.locales.some(l=>path===l.prefix+spec.route)),'Occupied G01 public route');
    }
